    if '</head>' in content:
        content = content.replace('</head>', apple_snippet + '</head>')
        Path(f).write_text(content, encoding='utf-8')
        print(f'{f}: injected Apple HIG safe area')
    else:
        print(f'{f}: no </head> tag found')
